"""
DocuSeal Service — Orchestrates e-sign submissions and template mapping.
"""

import json
import logging
import os
from typing import Any, Dict, List, Optional

import httpx
from structured_logging import logger as struct_logger

# Env vars (set in Cloud Run)
API_URL = os.environ.get("DOCUSEAL_API_URL", "")
API_TOKEN = os.environ.get("DOCUSEAL_API_TOKEN", "")
WEBHOOK_SECRET = os.environ.get("DOCUSEAL_WEBHOOK_SECRET", "")

# Local mapping file generated by tools/docuseal_template_uploader.py
MAPPING_FILE = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
    "config",
    "docuseal_templates.json",
)

_template_cache: Dict[str, Dict[str, Any]] = {}


def _load_templates():
    """Load filename -> {id, fields} mapping from disk."""
    global _template_cache
    if _template_cache:
        return _template_cache

    if os.path.exists(MAPPING_FILE):
        try:
            with open(MAPPING_FILE, "r", encoding="utf-8") as f:
                _template_cache = json.load(f)
        except Exception as e:
            struct_logger.error("Failed to load DocuSeal templates", error=str(e))
    return _template_cache


def get_template_id(filename: str) -> Optional[int]:
    """Resolve a PDF filename to its DocuSeal template ID."""
    templates = _load_templates()
    entry = templates.get(filename)
    if entry:
        return entry.get("docuseal_template_id")
    return None


async def send_for_signature(
    *,
    email: str,
    name: str,
    template_name: str,
    deal_id: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
    values: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Send a document for signature via DocuSeal.
    
    Returns a success/error dict.
    """
    if not API_URL or not API_TOKEN:
        return {
            "success": False,
            "status": "not_configured",
            "error": "DocuSeal API credentials not set",
        }

    template_id = get_template_id(template_name)
    if not template_id:
        # If not found in mapping, try using template_name as ID (backward compat)
        try:
            template_id = int(template_name)
        except (ValueError, TypeError):
            return {
                "success": False,
                "error": f"Template mapping not found for {template_name}",
            }

    payload = {
        "template_id": template_id,
        "send_email": True,
        "submitters": [
            {
                "role": "Buyer",
                "email": email,
                "name": name,
                "values": values or {},
            }
        ],
        "metadata": {
            "deal_id": deal_id,
            "template_name": template_name,
            **(metadata or {}),
        },
    }

    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.post(
                f"{API_URL.rstrip('/')}/api/submissions",
                headers={
                    "X-Auth-Token": API_TOKEN,
                    "Content-Type": "application/json",
                },
                json=payload,
            )
            if resp.status_code >= 400:
                error_detail = resp.text
                try:
                    error_detail = resp.json()
                except:
                    pass
                struct_logger.error(
                    "DocuSeal API error",
                    status_code=resp.status_code,
                    detail=error_detail,
                    template=template_name,
                )
                return {
                    "success": False,
                    "error": f"DocuSeal API returned {resp.status_code}",
                    "detail": error_detail,
                }
            
            return {"success": True, "submission": resp.json()}
    except Exception as exc:
        struct_logger.error("DocuSeal submission failed", error=str(exc))
        return {"success": False, "error": str(exc)}


async def send_file_for_signature(
    *,
    email: str,
    name: str,
    file_path: str,
    display_name: str,
    deal_id: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Upload a local PDF file to DocuSeal and send it for signature.
    
    Used for custom-generated packets that aren't fixed templates.
    """
    if not API_URL or not API_TOKEN:
        return {"success": False, "error": "DocuSeal credentials missing"}

    if not os.path.exists(file_path):
        return {"success": False, "error": f"File not found: {file_path}"}

    try:
        import base64
        with open(file_path, "rb") as f:
            file_content = base64.b64encode(f.read()).decode("utf-8")

        payload = {
            "send_email": True,
            "documents": [
                {
                    "name": display_name,
                    "file": file_content,
                }
            ],
            "submitters": [
                {
                    "role": "Buyer",
                    "email": email,
                    "name": name,
                }
            ],
            "metadata": {
                "deal_id": deal_id,
                "is_custom_file": True,
                **(metadata or {}),
            },
        }

        async with httpx.AsyncClient(timeout=30) as client:
            resp = await client.post(
                f"{API_URL.rstrip('/')}/api/submissions",
                headers={
                    "X-Auth-Token": API_TOKEN,
                    "Content-Type": "application/json",
                },
                json=payload,
            )
            if resp.status_code >= 400:
                return {"success": False, "error": f"DocuSeal API error {resp.status_code}", "detail": resp.text}
            
            return {"success": True, "submission": resp.json()}

    except Exception as exc:
        struct_logger.error("DocuSeal file submission failed", error=str(exc))
        return {"success": False, "error": str(exc)}


async def maybe_trigger_automated_signing(
    *,
    event_type: str,
    payload: Dict[str, Any],
) -> None:
    """
    Trigger automated e-sign envelopes based on business events.
    
    Supported events:
      - lead.captured: Send Welcome/Disclosure
      - deal.status_change: Send contract when status becomes 'contract'
    """
    if event_type == "lead.captured":
        email = payload.get("email")
        name = payload.get("name")
        if email and name:
            # Automate Credit Auth early to save time later
            await send_for_signature(
                email=email,
                name=name,
                template_name="State_CreditAuth.pdf",
                metadata={"trigger": "lead.captured"},
            )

    elif event_type == "deal.status_change":
        new_status = payload.get("to")
        deal_id = payload.get("deal_id")
        deal_data = payload.get("deal_data", {})
        
        email = deal_data.get("buyer_email")
        name = f"{deal_data.get('buyer_first_name', '')} {deal_data.get('buyer_last_name', '')}".strip()
        
        if not email or not name or not deal_id:
            return

        if new_status == "contract":
            # Automate the big one: Sales Contract
            await send_for_signature(
                email=email,
                name=name,
                template_name="TMHA_SalesContract.pdf",
                deal_id=deal_id,
                metadata={"trigger": "deal.status_change.contract"},
            )
        elif new_status == "pending":
            # Automate Deposit Agreement
            await send_for_signature(
                email=email,
                name=name,
                template_name="TMHA-SalesContractDepositAgreement.pdf",
                deal_id=deal_id,
                metadata={"trigger": "deal.status_change.pending"},
            )
